    const localPieceThemeBasePath = "assets/pieces";
    const pieceAssetFiles = Object.freeze({
      wk: "wK.svg", wq: "wQ.svg", wr: "wR.svg", wb: "wB.svg", wn: "wN.svg", wp: "wP.svg",
      bk: "bK.svg", bq: "bQ.svg", br: "bR.svg", bb: "bB.svg", bn: "bN.svg", bp: "bP.svg"
    });
    const requestedPieceSvgThemes = Object.freeze([
      "cburnett", "chessnut", "alpha", "merida", "dubrovny", "fantasy", "fresca", "pixel", "pirouetti", "gioco",
      "governor", "icpieces", "kiwen-suwi", "kosal", "leipzig", "letter", "maestro", "spatial", "staunty", "tatiana"
    ]);
    const licensedPieceAssetSets = Object.freeze(Object.fromEntries(requestedPieceSvgThemes.map((theme) => [
      theme,
      Object.freeze(Object.fromEntries(Object.entries(pieceAssetFiles).map(([piece, file]) => [piece, `${localPieceThemeBasePath}/${theme}/${file}`])))
    ])));
    const supportedPieceSvgSets = new Set(Object.keys(licensedPieceAssetSets));
    let activePieceSvgSet = "chessnut";
    let pieceSvgRenderVersion = 0;
    const pieceSvgMarkupCache = new Map();
    // The Chessnut migration keeps the existing board API intact: callers still
    // pass either FEN characters or chess.js piece objects to this renderer.
    const pieceCodeLookup = Object.freeze({
      K: { color: "w", type: "k" }, Q: { color: "w", type: "q" }, R: { color: "w", type: "r" },
      B: { color: "w", type: "b" }, N: { color: "w", type: "n" }, P: { color: "w", type: "p" },
      k: { color: "b", type: "k" }, q: { color: "b", type: "q" }, r: { color: "b", type: "r" },
      b: { color: "b", type: "b" }, n: { color: "b", type: "n" }, p: { color: "b", type: "p" }
    });
    const accessiblePieceNames = Object.freeze({ p: "pawn", n: "knight", b: "bishop", r: "rook", q: "queen", k: "king" });

    function getPieceCodeInfo(piece) {
      if (!piece) return null;
      if (typeof piece === "object" && /^(w|b)$/.test(piece.color) && /^[kqrbnp]$/.test(piece.type)) {
        return { color: piece.color, type: piece.type };
      }
      return pieceCodeLookup[String(piece)] || null;
    }

    function getAccessibleSquareLabel(squareName, piece, states = []) {
      const info = getPieceCodeInfo(piece);
      const content = info
        ? `${info.color === "w" ? "white" : "black"} ${accessiblePieceNames[info.type] || "piece"}`
        : "empty";
      return [squareName, content, ...states.filter(Boolean)].join(", ");
    }

    function getFocusedBoardSquare(board) {
      const active = document.activeElement;
      if (!(active instanceof HTMLElement) || !board?.contains(active)) return "";
      return active.dataset.square || "";
    }

    function restoreBoardFocus(board, squareName) {
      if (!board || !squareName) return;
      const square = board.querySelector(`[data-square="${squareName}"]`);
      if (square instanceof HTMLElement) square.focus({ preventScroll: true });
    }

    function resolvePieceSvgSet(style) {
      const requested = String(style || "chessnut").toLowerCase();
      return supportedPieceSvgSets.has(requested) ? requested : "chessnut";
    }

    const prewarmedPieceAssets = new Set();
    function getPieceSvgTheme(style) {
      const theme = pieceSetThemes?.[style] || pieceSetThemes?.chessnut || {};
      return {
        rarity: theme.rarity || "Common",
        whiteFill: theme.vars?.["--piece-white-fill"] || "#fff8ed",
        whiteStroke: theme.vars?.["--piece-white-stroke"] || "rgba(93, 64, 42, 0.72)",
        blackFill: theme.vars?.["--piece-black-fill"] || "#1d1814",
        blackStroke: theme.vars?.["--piece-black-stroke"] || "rgba(255, 248, 237, 0.42)",
        glow: theme.vars?.["--piece-preview-glow"] || "rgba(231, 182, 93, 0.2)"
      };
    }

    function createPieceSvgMarkup(piece, style = activePieceSvgSet, forceClassic = false) {
      const info = getPieceCodeInfo(piece);
      if (!info) return "";
      const colorClass = info.color === "w" ? "white-piece" : "black-piece";
      const resolvedStyle = forceClassic ? "chessnut" : resolvePieceSvgSet(style);
      const theme = getPieceSvgTheme(resolvedStyle);
      const cacheKey = `${resolvedStyle}:${info.color}:${info.type}`;
      const cached = pieceSvgMarkupCache.get(cacheKey);
      if (cached) return cached;
      const asset = licensedPieceAssetSets[resolvedStyle]?.[`${info.color}${info.type}`];
      if (!asset) return "";
      const markup = `<img class="piece-svg ${colorClass}" src="${asset}" alt="" aria-hidden="true" draggable="false" decoding="async" fetchpriority="auto" referrerpolicy="no-referrer" data-piece="${info.color}${info.type}" data-style="${resolvedStyle}" data-rarity="${theme.rarity}">`;
      pieceSvgMarkupCache.set(cacheKey, markup);
      return markup;
    }

    function createPieceFallbackElement(piece, style = activePieceSvgSet) {
      const info = getPieceCodeInfo(piece);
      if (!info) return null;
      const symbols = {
        wk: "♔", wq: "♕", wr: "♖", wb: "♗", wn: "♘", wp: "♙",
        bk: "♚", bq: "♛", br: "♜", bb: "♝", bn: "♞", bp: "♟"
      };
      const symbol = symbols[`${info.color}${info.type}`];
      if (!symbol) return null;
      const fallback = document.createElement("span");
      fallback.className = `piece-symbol ${info.color === "w" ? "white-piece" : "black-piece"}`;
      fallback.dataset.symbol = symbol;
      fallback.dataset.rarity = getPieceSvgTheme(resolvePieceSvgSet(style)).rarity;
      fallback.textContent = symbol;
      fallback.setAttribute("aria-hidden", "true");
      return fallback;
    }

    function prewarmPieceSvgSet(style = activePieceSvgSet) {
      const resolvedStyle = resolvePieceSvgSet(style);
      Object.values(licensedPieceAssetSets[resolvedStyle] || licensedPieceAssetSets.chessnut).forEach((asset) => {
        if (prewarmedPieceAssets.has(asset)) return;
        prewarmedPieceAssets.add(asset);
        const image = new Image();
        image.decoding = "async";
        image.src = asset;
      });
      ["K", "Q", "R", "B", "N", "P", "k", "q", "r", "b", "n", "p"].forEach((piece) => createPieceSvgMarkup(piece, resolvedStyle));
    }

    function schedulePieceSvgPrewarm(style = activePieceSvgSet) {
      const task = () => prewarmPieceSvgSet(style);
      if (typeof scheduleBackgroundTask === "function") {
        scheduleBackgroundTask(task, 600, `piece-svg-prewarm:${resolvePieceSvgSet(style)}`);
        return;
      }
      window.setTimeout(task, 0);
    }

    function renderPieceOnSquare(square, piece, style = activePieceSvgSet, forceClassic = false) {
      const markup = createPieceSvgMarkup(piece, style, forceClassic);
      square.textContent = "";
      if (!piece) return;
      const showFallback = () => {
        const fallback = createPieceFallbackElement(piece, forceClassic ? "chessnut" : style);
        if (fallback) square.replaceChildren(fallback);
      };
      if (!markup) {
        showFallback();
        return;
      }
      square.innerHTML = markup;
      const image = square.querySelector(".piece-svg");
      if (!image) {
        showFallback();
        return;
      }
      image.addEventListener("error", () => {
        if (image.parentElement === square) showFallback();
      }, { once: true });
      if (image.complete && !image.naturalWidth) showFallback();
    }

