    function buildQuickPuzzleBatch(mode, seeds) {
      return seeds.map(([title, level, theme, fen, target, move, hint, feedback], index) => ({
        level,
        mode,
        theme,
        side: "White to move",
        title: `${mode} ${String(index + 1).padStart(2, "0")}: ${title}`,
        prompt: "Fast mission: find the one move that wins the moment.",
        fen,
        targets: [target],
        hint,
        line: [move],
        answers: [
          { move, correct: true },
          { move: "Look again", correct: false },
          { move: "Try safer", correct: false }
        ],
        feedback
      }));
    }

    function buildGamePuzzleBatch(seeds) {
      return seeds.map(([title, level, theme, side, fen, targets, line, hint, feedback], index) => ({
        level,
        mode: "Puzzle Adventure",
        theme,
        side,
        title: `Game Puzzle ${String(index + 1).padStart(2, "0")}: ${title}`,
        prompt: "Game-style mission: find the forcing move, then follow the continuation.",
        fen,
        targets,
        hint,
        line,
        answers: [
          { move: line[0], correct: true },
          { move: "Check first", correct: false },
          { move: "Try safer", correct: false }
        ],
        feedback
      }));
    }

