      function fenBoardToMap(boardFen) {
        const map = {};
        boardFen.split("/").forEach((row, rowIndex) => {
          let fileIndex = 0;
          [...row].forEach((char) => {
            const empty = Number(char);
            if (empty) {
              fileIndex += empty;
            } else {
              map[`${String.fromCharCode(97 + fileIndex)}${8 - rowIndex}`] = char;
              fileIndex += 1;
            }
          });
        });
        return map;
      }

      function mapToFenBoard(map) {
        const rows = [];
        for (let rank = 8; rank >= 1; rank -= 1) {
          let row = "";
          let empty = 0;
          for (let fileIndex = 0; fileIndex < 8; fileIndex += 1) {
            const square = `${String.fromCharCode(97 + fileIndex)}${rank}`;
            if (map[square]) {
              if (empty) row += empty;
              empty = 0;
              row += map[square];
            } else {
              empty += 1;
            }
          }
          if (empty) row += empty;
          rows.push(row);
        }
        return rows.join("/");
      }

      function getLineBlockSquares(line = []) {
        const blocked = new Set();
        line.forEach((move) => {
          const match = String(move).match(/^([a-h][1-8])([a-h][1-8])/i);
          if (!match) return;
          const [, from, to] = match.map((item) => item.toLowerCase());
          blocked.add(from);
          blocked.add(to);
          const df = Math.sign(to.charCodeAt(0) - from.charCodeAt(0));
          const dr = Math.sign(Number(to[1]) - Number(from[1]));
          const isRay = from[0] === to[0] || from[1] === to[1] || Math.abs(to.charCodeAt(0) - from.charCodeAt(0)) === Math.abs(Number(to[1]) - Number(from[1]));
          if (!isRay) return;
          let file = from.charCodeAt(0) + df;
          let rank = Number(from[1]) + dr;
          while (`${String.fromCharCode(file)}${rank}` !== to) {
            blocked.add(`${String.fromCharCode(file)}${rank}`);
            file += df;
            rank += dr;
          }
        });
        return blocked;
      }

      function buildNoisyFen(template, salt) {
        const parts = template.fen.split(/\s+/);
        const map = fenBoardToMap(parts[0]);
        const blocked = new Set([...(template.block || []), ...getLineBlockSquares(template.line)]);
        const noise = [
          ..."abcdefgh".split("").flatMap((file) => [`${file}2`, `${file}3`].map((square) => [square, "P"])),
          ..."abcdefgh".split("").flatMap((file) => [`${file}6`, `${file}7`].map((square) => [square, "p"]))
        ].filter(([square]) => !map[square] && !blocked.has(square));
        const count = 2 + (salt % 5);
        const rankedNoise = noise
          .map((entry, index) => ({ entry, score: (((salt + 31) * (index + 17) * 2654435761) + index * 1013904223) >>> 0 }))
          .sort((a, b) => a.score - b.score)
          .map((item) => item.entry);
        for (let used = 0; used < count && rankedNoise.length; used += 1) {
          const [square, piece] = rankedNoise[used % rankedNoise.length];
          if (!map[square]) map[square] = piece;
        }
        return `${mapToFenBoard(map)} ${parts[1]} ${parts[2] || "-"} ${parts[3] || "-"} 0 1`;
      }

