    function expandCoreBeginnerTutorialMoves() {
      const followUps = {
        setup: [["g1", "f3"], ["f1", "c4"]],
        pawn: [["e4", "e5"]],
        rook: [["a8", "h8"]],
        bishop: [["b5", "e8"]],
        knight: [["f3", "e5"]],
        queen: [["h5", "e2"]],
        king: [["f1", "e2"]],
        capture: [["f7", "g8"]],
        check: [["e7", "a7"]],
        mate: [["f8", "a8"]],
        castle: [["f1", "e1"], ["g1", "g2"]],
        "en-passant": [["d6", "d7"]],
        promotion: [["a8", "a7"]],
        opening: [["f1", "c4"], ["e1", "g1", ["g1"], "Castle after developing.", "castle"]],
        fork: [["e7", "c8"], ["c8", "b6"]],
        pin: [["b5", "c6"], ["c6", "d7"]],
        skewer: [["e8", "d7"]],
        discovered: [["c4", "e6"]]
      };
      beginnerTutorialLessons.forEach((lesson) => {
        if (lesson.moves) return;
        lesson.moves = [
          { from: lesson.from, to: lesson.correct, targets: lesson.targets, coach: lesson.coach, special: lesson.special },
          ...(followUps[lesson.id] || []).map(([from, to, targets, coach, special]) => ({
            from,
            to,
            targets: targets || [to],
            coach: coach || lesson.coach,
            special
          }))
        ];
      });
    }
    expandCoreBeginnerTutorialMoves();
