    const boardRarityRank = { Common: 1, Rare: 2, Epic: 3, Legendary: 4, Mythic: 5, Divine: 6 };
    let boardThemeStoreUi = { search: "", rarity: "all", sort: "rarity", preview: "wood" };

    function getBoardThemeItem(value) {
      return boardThemeStoreItems.find((item) => item.value === value) || boardThemeStoreItems[0];
    }

    function getFilteredBoardThemeItems(items, prefs = readLearnerPrefs()) {
      const query = boardThemeStoreUi.search.trim().toLowerCase();
      const owned = new Set(storeState.owned || []);
      return items.filter((item) => {
        if (boardThemeStoreUi.rarity !== "all" && item.rarity !== boardThemeStoreUi.rarity) return false;
        if (!query) return true;
        return [item.name, item.description, item.rarity, item.tag].some((value) => String(value).toLowerCase().includes(query));
      }).sort((a, b) => {
        if (boardThemeStoreUi.sort === "price") return (a.cost || 0) - (b.cost || 0);
        if (boardThemeStoreUi.sort === "name") return a.name.localeCompare(b.name);
        if (boardThemeStoreUi.sort === "owned") return Number(owned.has(b.id) || prefs.board === b.value) - Number(owned.has(a.id) || prefs.board === a.value);
        return (boardRarityRank[a.rarity] || 0) - (boardRarityRank[b.rarity] || 0) || (a.cost || 0) - (b.cost || 0);
      });
    }

