    const warmedResourceOrigins = new Set();

    function warmResourceOrigins(origins) {
      const list = Array.isArray(origins) ? origins : [origins];
      list.forEach((origin) => {
        if (!origin || warmedResourceOrigins.has(origin)) return;
        warmedResourceOrigins.add(origin);
        const hint = document.createElement("link");
        hint.rel = "preconnect";
        hint.href = origin;
        hint.crossOrigin = "anonymous";
        document.head.append(hint);
      });
    }
    const stockfishDebugMode = (() => {
      try {
        return new URLSearchParams(window.location.search).has("stockfishDebug")
          || localStorage.getItem("stockfishDebug") === "1";
      } catch {
        return false;
      }
    })();
